-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_JIMDO_TEASER.SNOWBOTS.T_CLOSE_SENTINEL
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Berlin'
  CONFIG = '{"autonomy": 3}'
  WHEN SYSTEM$STREAM_HAS_DATA('SDP_JIMDO_TEASER.PUBLIC.STR_GL_JOURNAL')
AS
  CALL SDP_JIMDO_TEASER.SNOWBOTS.SP_RUN_BOT('close-sentinel');

-- step 1 · Actuals landed: October orders + settlements
SELECT SYSTEM$STREAM_HAS_DATA('SDP_JIMDO_TEASER.PUBLIC.STR_BILLING_ORDERS') OR SYSTEM$STREAM_HAS_DATA('SDP_JIMDO_TEASER.PUBLIC.STR_SETTLEMENTS');
-- step 2 · Completeness DMFs per feed
SELECT feed, SNOWFLAKE.CORE.ROW_COUNT(...) AS rows_loaded, expected_rows,
       rows_loaded / expected_rows AS completeness
FROM SDP_JIMDO_TEASER.SNOWBOTS.V_FEED_EXPECTATIONS WHERE period = '2026-10';
-- step 3 · Fallback: settle from the billing ledger for the late file
CALL SDP_JIMDO_TEASER.SNOWBOTS.SP_BACKFILL_FROM_LEDGER('SETTLEMENTS', '2026-10');
-- step 4 · Reconcile: orders ↔ payments ↔ credit memos
CALL SDP_JIMDO_TEASER.SNOWBOTS.SP_RECONCILE(period => '2026-10', tolerance_pct => 0.2);
-- step 5 · Guardrail: completeness ≥ 99% and difference = 0
SELECT MIN(completeness) >= 0.99 AND ABS(SUM(diff)) = 0 FROM SDP_JIMDO_TEASER.SNOWBOTS.V_CLOSE_STATUS WHERE period = '2026-10';
-- step 6 · Lock period 2026-10 (awaiting approval)
CALL SDP_JIMDO_TEASER.PUBLIC.SP_LOCK_PERIOD('2026-10', approved_by => :approver);

