-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_JIMDO_TEASER.SNOWBOTS.T_DRIVER_REFRESH
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Berlin'
  CONFIG = '{"autonomy": 4}'
AS
  CALL SDP_JIMDO_TEASER.SNOWBOTS.SP_RUN_BOT('driver-refresh');

-- step 1 · Marketplace share refreshed
SELECT MAX(period) FROM SDP_JIMDO_TEASER.PUBLIC.JIMDO_MACRO_DRIVERS;
-- step 2 · Upsert macro drivers
MERGE INTO SDP_JIMDO_TEASER.PUBLIC.JIMDO_MACRO_DRIVERS t USING (SELECT * FROM MACRO_MARKETPLACE.PUBLIC.EU_INDICATORS WHERE period = DATE_TRUNC(month, CURRENT_DATE)) s ON t.period = s.period ...;
-- step 3 · Guardrail: monthly move ≤ 5%
SELECT MAX(ABS(pct_change)) <= 0.05 FROM SDP_JIMDO_TEASER.SNOWBOTS.V_DRIVER_MOVES;
-- step 4 · Recalculate acquisition cost for the open months
CALL SDP_JIMDO_TEASER.PUBLIC.SP_RECALC(scope => 'SALES_MARKETING', from_period => '2026-11');
-- step 5 · One-line impact note
SELECT AI_COMPLETE('claude-sonnet-4-5', 'One sentence on: ' || :impact_json);

