  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Berlin'
  CONFIG = '{"autonomy": 1}'
AS
  CALL SDP_JIMDO_TEASER.SNOWBOTS.SP_RUN_BOT('spend-guardian');

-- step 1 · Renewals due ≤ 90 days
SELECT * FROM SDP_JIMDO_TEASER.PUBLIC.DIM_CONTRACT WHERE renewal_date <= DATEADD(day, 90, CURRENT_DATE);
