SELECT c.vendor, c.unit_price / b.p50 - 1 AS premium FROM ... JOIN SDP_JIMDO_TEASER.SNOWBOTS.V_VENDOR_BENCHMARK b ...;
-- step 3 · Recommendations to Procurement
